```json
{
  "root_causes": [
    {
      "service": "ts-travel-plan-service",
      "fault_kind": "application_method_slow",
      "evidence": [
        {"kind": "trace", "sql": "SELECT service_name, span_name, attr_span_kind, count(*) n, round(avg(duration/1e6),1) avg_ms, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY 1,2,3 ORDER BY avg_ms DESC", "claim": "Travel-plan server spans average about 12.6 s for cheapest, quickest and minStation, with no errors."},
        {"kind": "trace", "sql": "SELECT p.span_name, round(p.duration/1e6,1) controller_ms, count(c.span_id) child_calls, round(sum(c.duration)/1e6,1) child_ms FROM abnormal_traces p LEFT JOIN abnormal_traces c ON c.parent_span_id=p.span_id AND c.trace_id=p.trace_id WHERE p.service_name='ts-travel-plan-service' AND p.span_name LIKE 'TravelPlanController.%' GROUP BY 1,2 ORDER BY controller_ms DESC LIMIT 20", "claim": "Travel-plan controller spans take many seconds while their child calls total only a few hundred milliseconds, so the time is spent inside the service."},
        {"kind": "trace", "sql": "SELECT service_name, count(*) n, round(avg(duration/1e6),1) avg_ms, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM normal_traces WHERE service_name='ts-travel-plan-service' AND attr_span_kind='Server' GROUP BY 1", "claim": "Before the incident the same service averaged about 621 ms with p95 about 2.8 s, so the slowdown is a large regression."},
        {"kind": "metric", "sql": "SELECT metric, round(avg(value),2) avg_abn FROM abnormal_metrics_sum WHERE attr_k8s_pod_name='ts-travel-plan-service-56754fc8bc-jr68c' AND metric IN ('jvm.cpu.time','jvm.class.loaded') GROUP BY 1", "claim": "Travel-plan JVM CPU time is not saturated during the incident; it is lower than normal, so CPU saturation is ruled out."}
      ]
    }
  ],
  "propagation": [
    {
      "from": "ts-travel-plan-service",
      "to": "ts-ui-dashboard",
      "evidence": [
        {"kind": "trace", "sql": "SELECT span_name, count(*) n, round(avg(duration/1e6),1) avg_ms, round(approx_quantile(duration/1e6,0.95),1) p95_ms FROM abnormal_traces WHERE service_name='ts-ui-dashboard' AND attr_span_kind='Server' AND span_name LIKE 'POST /api/v1/travelplanservice/%' GROUP BY 1 ORDER BY avg_ms DESC", "claim": "User-facing travelPlan requests at ts-ui-dashboard average 12.6–13.7 s during the incident, against about 0.6–0.7 s before."}
      ]
    }
  ]
}
```

